   "on_enter_first_entry_only": true,
   "task_message": "The customer has a hardship. Make no persuasion attempt and do not ask for any payment. If they accept the offer, call transfer_to_agent with queue support. If they decline, thank them and say goodbye, then call end_call. If the customer names a payment date or amount themselves, use these facts:
{{facts_text}}
read back product, amount and date, ask "Do you confirm?", and call create_promise only after a clear yes.",
   "tools": [
    {"type": "function", "config": {"timeoutMs": 12000, "maxRetries": 0}, "function": {"name": "transfer_to_agent", "handler": "__function__:api_call", "description": "Hand the call to the customer support team. CALL it when the customer accepts the offer.", "parameters": {"type": "object", "properties": {
     "url": {"type": "string", "default": "https://freya-bank-mock.freyavoice.workers.dev/v1/transfer_to_agent"},
