     "post_process_code": "try:
    result.pop('header', None)
    d = result.get('data')
    ok = isinstance(d, dict) and str(d.get('ok')).lower() == 'true'
    if ok:
        vars['close_outcome'] = 'transferred'
        vars['close_reason'] = 'support'
        vars['call_state'] = 'transferred'
        d['what_to_do_next'] = 'Transferred. Say a colleague will take over.'
    elif isinstance(d, dict):
        d['what_to_do_next'] = 'The transfer did not go through. Say so honestly, thank them and say goodbye.'
    else:
        result['what_to_do_next'] = 'The transfer did not go through. Say so honestly, thank them and say goodbye.'
except Exception:
    pass
"},
    {"type": "function", "config": {"timeoutMs": 12000, "maxRetries": 0}, "function": {"name": "create_promise", "handler": "__function__:api_call", "description": "Record a payment promise the customer offered themselves. CALL it only after a clear yes to the read-back.", "parameters": {"type": "object", "properties": {
     "url": {"type": "string", "default": "https://freya-bank-mock.freyavoice.workers.dev/v1/create_promise"},
     "method": {"type": "string", "default": "POST"},
     "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
     "body": {"type": "object", "required": ["customer_id", "product_id", "amount", "date"], "properties": {
      "customer_id": {"type": "string", "default": "{{customer_id}}"},
      "product_id": {"type": "string", "description": "product_id from the facts.", "default": "{{product_id}}"},
      "amount": {"type": "number", "description": "Amount as read back, e.g. 120.50.", "default": "{{amount}}"},
      "date": {"type": "string", "description": "Payment date as YYYY-MM-DD.", "default": "{{date}}"}}}}}},
     "pre_process_code": "import re
try:
    b = config.get('body')
    if isinstance(b, dict):
        if b.get('amount') not in (None, ''):
            b['amount'] = round(float(re.sub('[^0-9.]', '', str(b['amount']))), 2)
        b['date'] = str(b.get('date') or '').strip()[:10]
except Exception:
    pass
",
     "post_process_code": "try:
    result.pop('header', None)
    d = result.get('data')
    if isinstance(d, dict) and str(d.get('ok')).lower() == 'true':
        vars['promise_count'] = str(int(vars.get('promise_count') or 0) + 1)
        vars['close_outcome'] = 'promise'
        vars['close_reason'] = ''
        vars['call_state'] = 'promised'
        d['what_to_do_next'] = 'Recorded. Say: You will receive a text message confirming this promise.'
    else:
        tries = int(vars.get('promise_failures') or 0) + 1
        vars['promise_failures'] = str(tries)
        msg = 'NOT recorded. Do not say it was recorded. Call create_promise once more now with the same values.'
        if tries >= 2:
            vars['close_outcome'] = 'no_promise'
            vars['close_reason'] = 'service_error'
            vars['call_state'] = 'service_error'
            msg = 'NOT recorded. Say you could not record the promise.'
        if isinstance(d, dict):
            d['what_to_do_next'] = msg
        else:
            result['what_to_do_next'] = msg
except Exception:
    pass
"},
