    now = parse_now(vars.get('now'))
    h = hols()
    today = now.date()
    prods = list_from_vars(vars, 'products', ['load_account_response.data.products', 'get_account_response.data.products'])
    p = prods[0]
    typ = str(p.get('type') or '')
    if typ == 'credit_card':
        label = 'credit card ending ' + str(p.get('card_last4') or '')
        floor = p.get('minimum_payment')
    elif typ == 'car_loan':
        label = 'car loan'
        floor = p.get('instalment_amount')
    else:
        label = 'personal loan'
        floor = p.get('instalment_amount')
    due = float(p.get('past_due') or 0)
    floor = float(floor or 0)
    days = int(float(p.get('days_late') or 0))
    if days <= 7:
        band, n, att = 'early', 12, 1
    else:
        band, n, att = 'late', 7, 2
    deadline = add_bd(today, n, h)
    a1 = last_bd_week(today, h)
    if a1 is None or a1 <= today:
        a1 = last_bd_week(today + datetime.timedelta(days=7), h)
    if a1 is None or a1 > deadline:
        a1 = deadline
    rows = []
    for i in range(0, 22):
        d = today + datetime.timedelta(days=i)
        if is_bd(d, h):
            st = 'business day, ' + ('can be recorded' if d <= deadline else 'AFTER the deadline: offer the deadline instead')
        else:
            nb = next_bd(d, h)
            st = 'not a business day' + (' (bank holiday)' if d in h else '') + '; ' + (('offer the next business day ' + spoken(nb) + ' (' + nb.isoformat() + ')') if nb <= deadline else 'after the deadline: offer the deadline instead')
        rows.append('- ' + spoken(d) + ' (' + d.isoformat() + ')' + (' TODAY' if i == 0 else '') + ': ' + st)
    wk = []
    for idx, name in enumerate(WEEKDAYS):
        this = week_mon(today) + datetime.timedelta(days=idx)
